//! `HEADS.md`: the projection.
//!
//! Deliberately dull. Sorted, no timestamp, no prose, no history, so CI can
//! regenerate it and compare (after canonicalisation, section 12.2). It renders only heads, so a superseded entry
//! cannot appear in it, and it is never written at all when the graph failed
//! Layer A: a partial projection would be a false statement of current state
//! wearing the authority of a generated file.

use crate::graph::Graph;
use crate::model::{Slot, DEFAULT_SCOPE};

pub const HEADER: &str = "# Architecture decision heads";
pub const BANNER: &str = "Generated by `greentopo heads --write`. Do not edit.";

/// Markdown table cells carry `|`, which would split the row.
///
/// The backslash is escaped first, and that order is the whole correctness
/// argument: escaping only `|` turned the choice `A\|B` into `A\\|B`, which a
/// reader counting backslashes sees as an unescaped pipe and splits on,
/// producing a five-column row from a four-column one.
///
/// A newline cannot appear here — `parse` rejects one in `choice` and `reason`
/// before it ever reaches the projection — because there is no escape for it
/// in a markdown table row, and one would split a record across several.
fn cell(s: &str) -> String {
    s.trim().replace('\\', "\\\\").replace('|', "\\|")
}

/// Rewrite each backtick code span with the fence prettier prints for it.
///
/// A span's text is what CommonMark reads out of it: the characters between
/// the fences, less one space each side when both sides carry one. Prettier
/// prints that text inside the shortest run of backticks the text does not
/// itself contain, with a space of padding only when the text starts or ends
/// with a backtick, or starts and ends with a space. The span says the same
/// thing either way, so the fence is formatting: `--write` emits prettier's
/// (a choice written ``` ``x`` ``` would otherwise fail a repository's
/// prettier gate on every refresh) and canonicalisation compares fences in
/// this form, so a file written before either way stays current.
///
/// A backtick escaped by a backslash outside a span opens nothing and stays.
/// A run of backticks with no closing run is literal and stays. When a span
/// follows one, the cell is returned as it is: narrowing that span's fence
/// could make the earlier run close against it, moving what is code and what
/// is text (prettier leaves such a cell alone too).
fn minimal_fences(s: &str) -> String {
    let chars: Vec<char> = s.chars().collect();
    let mut out = String::with_capacity(s.len());
    let mut unclosed = false;
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '\\' && i + 1 < chars.len() {
            out.push(chars[i]);
            out.push(chars[i + 1]);
            i += 2;
            continue;
        }
        if chars[i] != '`' {
            out.push(chars[i]);
            i += 1;
            continue;
        }
        let run = backtick_run(&chars, i);
        let mut j = i + run;
        let mut close = None;
        while j < chars.len() {
            if chars[j] == '`' {
                let r = backtick_run(&chars, j);
                if r == run {
                    close = Some(j);
                    break;
                }
                j += r;
            } else {
                j += 1;
            }
        }
        let Some(end) = close else {
            unclosed = true;
            out.extend(chars[i..i + run].iter());
            i += run;
            continue;
        };
        if unclosed {
            return s.to_string();
        }
        let mut text: &[char] = &chars[i + run..end];
        if text.len() >= 2
            && text[0] == ' '
            && text[text.len() - 1] == ' '
            && text.iter().any(|&c| c != ' ')
        {
            text = &text[1..text.len() - 1];
        }
        let mut fence = 1;
        while has_run_of(text, fence) {
            fence += 1;
        }
        let fence: String = "`".repeat(fence);
        // CommonMark would strip one space from each side of a text that
        // starts and ends with one, so such a text needs the gap as well.
        let spaced = text.first() == Some(&' ')
            && text.last() == Some(&' ')
            && text.iter().any(|&c| c != ' ');
        let gap = if spaced || text.first() == Some(&'`') || text.last() == Some(&'`') {
            " "
        } else {
            ""
        };
        out.push_str(&fence);
        out.push_str(gap);
        out.extend(text.iter());
        out.push_str(gap);
        out.push_str(&fence);
        i = end + run;
    }
    out
}

fn backtick_run(chars: &[char], at: usize) -> usize {
    chars[at..].iter().take_while(|&&c| c == '`').count()
}

/// Whether `text` holds a run of exactly `n` backticks.
fn has_run_of(text: &[char], n: usize) -> bool {
    let mut i = 0;
    while i < text.len() {
        if text[i] == '`' {
            let r = backtick_run(text, i);
            if r == n {
                return true;
            }
            i += r;
        } else {
            i += 1;
        }
    }
    false
}

/// Pad every table the way prettier aligns one, so a repository that runs
/// prettier over its markdown finds `HEADS.md` already formatted.
///
/// Only `heads --write` calls this; `heads` prints the compact render, which is
/// what a session reads. Padding, the delimiter row's dashes and a code span's
/// fence (`minimal_fences`) are what canonicalisation erases (section 12.2),
/// so the aligned file and the compact render compare equal.
///
/// Each column is as wide as its widest cell, three at least, measured with
/// `display_width`. Lines outside a table pass through unchanged. A row keeps
/// its own number of cells: the render never writes a short one, and padding
/// one out would add a column the comparison counts. Any line that starts and
/// ends with `|` counts as a row, as it does for `canonical_row`; the render
/// has no fenced block for one to hide in.
pub fn align(text: &str) -> String {
    let lines: Vec<&str> = text.split_inclusive('\n').collect();
    let mut out = String::with_capacity(text.len() * 2);
    let mut i = 0;
    while i < lines.len() {
        if !is_table_row(lines[i]) {
            out.push_str(lines[i]);
            i += 1;
            continue;
        }
        let start = i;
        while i < lines.len() && is_table_row(lines[i]) {
            i += 1;
        }
        out.push_str(&align_table(&lines[start..i]));
    }
    out
}

fn is_table_row(line: &str) -> bool {
    let t = line.trim_end_matches('\n');
    t.len() >= 2 && t.starts_with('|') && t.ends_with('|')
}

fn align_table(rows: &[&str]) -> String {
    let rows: Vec<Vec<String>> = rows
        .iter()
        .map(|r| {
            let t = r.trim_end_matches('\n');
            split_unescaped(&t[1..t.len() - 1])
                .into_iter()
                .map(|f| minimal_fences(f.trim()))
                .collect()
        })
        .collect();
    let delimiter = |row: &Vec<String>| row.iter().all(|f| is_delimiter_field(f));
    let columns = rows.iter().map(Vec::len).max().unwrap_or(0);
    let mut widths = vec![3; columns];
    for row in rows.iter().filter(|r| !delimiter(r)) {
        for (w, f) in widths.iter_mut().zip(row) {
            *w = (*w).max(display_width(f));
        }
    }
    let mut out = String::new();
    for row in &rows {
        out.push('|');
        for (f, w) in row.iter().zip(&widths) {
            out.push(' ');
            if delimiter(row) {
                out.push_str(&"-".repeat(*w));
            } else {
                out.push_str(f);
                out.push_str(&" ".repeat(w.saturating_sub(display_width(f))));
            }
            out.push_str(" |");
        }
        out.push('\n');
    }
    out
}

/// The width prettier gives a string when it aligns a table.
///
/// An approximation of prettier's `getStringWidth`, which counts an emoji
/// (with its modifiers, variation selector and joined parts) as two columns,
/// an East Asian wide or fullwidth character as two, a control or combining
/// character as none, and anything else as one. A miss here costs only a
/// prettier reformat; freshness never reads the padding.
pub fn display_width(s: &str) -> usize {
    let mut width = 0;
    // Whether the previous character was an emoji, and so whether a joiner,
    // modifier or variation selector after it belongs to it.
    let mut in_emoji = false;
    let mut joined = false;
    let mut prev = 0u32;
    for c in s.chars() {
        let cp = c as u32;
        if cp <= 0x1f || (0x7f..=0x9f).contains(&cp) || (0x300..=0x36f).contains(&cp) {
            continue;
        }
        if cp == 0x200d && in_emoji {
            joined = true;
            continue;
        }
        if (0x1f3fb..=0x1f3ff).contains(&cp) && in_emoji {
            continue;
        }
        if cp == 0xfe0f {
            // Part of an emoji already counted, or a text-style symbol made
            // an emoji (`❤` is one column, `❤️` two); either way the
            // sequence is two columns once this is counted.
            if !in_emoji {
                width += 1;
                in_emoji = (0x2000..=0x2bff).contains(&prev);
            }
            continue;
        }
        if joined {
            // The part after a zero-width joiner shares the emoji's columns.
            joined = false;
            if is_pictographic(cp) || is_wide(cp) {
                prev = cp;
                continue;
            }
        }
        prev = cp;
        if is_pictographic(cp) {
            width += 2;
            in_emoji = true;
            continue;
        }
        let wide = is_wide(cp);
        in_emoji = wide && (0x2300..=0x2bff).contains(&cp);
        width += if wide { 2 } else { 1 };
    }
    width
}

/// Emoji outside the ranges `is_wide` names, all two columns wide.
fn is_pictographic(cp: u32) -> bool {
    (0x1f300..=0x1f64f).contains(&cp)
        || (0x1f680..=0x1f6ff).contains(&cp)
        || (0x1f7e0..=0x1f7eb).contains(&cp)
        || (0x1f90c..=0x1f9ff).contains(&cp)
        || (0x1fa70..=0x1faff).contains(&cp)
        || matches!(cp, 0x1f004 | 0x1f0cf | 0x1f18e)
        || (0x1f191..=0x1f19a).contains(&cp)
        || (0x1f200..=0x1f251).contains(&cp)
}

/// East Asian Wide and Fullwidth (Unicode UAX #11), the ranges that matter
/// in prose: Hangul, CJK, kana, fullwidth forms, and the symbols in the
/// U+2300–U+2BFF blocks that default to emoji presentation.
fn is_wide(cp: u32) -> bool {
    const RANGES: &[(u32, u32)] = &[
        (0x1100, 0x115f),
        (0x231a, 0x231b),
        (0x2329, 0x232a),
        (0x23e9, 0x23ec),
        (0x23f0, 0x23f0),
        (0x23f3, 0x23f3),
        (0x25fd, 0x25fe),
        (0x2614, 0x2615),
        (0x2648, 0x2653),
        (0x267f, 0x267f),
        (0x2693, 0x2693),
        (0x26a1, 0x26a1),
        (0x26aa, 0x26ab),
        (0x26bd, 0x26be),
        (0x26c4, 0x26c5),
        (0x26ce, 0x26ce),
        (0x26d4, 0x26d4),
        (0x26ea, 0x26ea),
        (0x26f2, 0x26f3),
        (0x26f5, 0x26f5),
        (0x26fa, 0x26fa),
        (0x26fd, 0x26fd),
        (0x2705, 0x2705),
        (0x270a, 0x270b),
        (0x2728, 0x2728),
        (0x274c, 0x274c),
        (0x274e, 0x274e),
        (0x2753, 0x2755),
        (0x2757, 0x2757),
        (0x2795, 0x2797),
        (0x27b0, 0x27b0),
        (0x27bf, 0x27bf),
        (0x2b1b, 0x2b1c),
        (0x2b50, 0x2b50),
        (0x2b55, 0x2b55),
        (0x2e80, 0x303e),
        (0x3041, 0x33ff),
        (0x3400, 0x4dbf),
        (0x4e00, 0x9fff),
        (0xa000, 0xa4cf),
        (0xa960, 0xa97f),
        (0xac00, 0xd7a3),
        (0xf900, 0xfaff),
        (0xfe10, 0xfe19),
        (0xfe30, 0xfe6f),
        (0xff00, 0xff60),
        (0xffe0, 0xffe6),
        (0x17000, 0x18aff),
        (0x1b000, 0x1b2ff),
        (0x20000, 0x3fffd),
    ];
    RANGES.iter().any(|&(lo, hi)| (lo..=hi).contains(&cp))
}

fn scope_cell(scope: &str) -> String {
    if scope == DEFAULT_SCOPE {
        "—".to_string()
    } else {
        cell(scope)
    }
}

pub fn render(g: &Graph) -> String {
    let mut active: Vec<(String, String, String, String)> = Vec::new();
    let mut retired: Vec<(String, String, String)> = Vec::new();

    for slot in g.corpus().slots() {
        let h = g.heads(slot);
        // More than one head is a contradiction, and a projection must not
        // quietly print one of them. `check` reports it; `heads` stays silent
        // rather than picking.
        let [(adr, entry)] = h[..] else { continue };
        match entry.choice() {
            Some(c) => active.push((
                slot.key.to_string(),
                slot.scope.to_string(),
                adr.id.to_string(),
                c.to_string(),
            )),
            None => retired.push((
                slot.key.to_string(),
                slot.scope.to_string(),
                adr.id.to_string(),
            )),
        }
    }

    let decided: Vec<&str> = g
        .corpus()
        .slots()
        .iter()
        .filter(|s| !g.heads(**s).is_empty())
        .map(|s| s.key)
        .collect();
    let mut undecided: Vec<&str> = g
        .registry()
        .keys
        .iter()
        .map(|k| k.name.as_str())
        .filter(|k| !decided.contains(k))
        .collect();

    active.sort();
    retired.sort();
    undecided.sort();

    let mut out = String::new();
    out.push_str(HEADER);
    out.push_str("\n\n");
    out.push_str(BANNER);
    out.push_str("\n\n## Active\n\n");
    if active.is_empty() {
        out.push_str("None.\n");
    } else {
        out.push_str("| Key | Scope | Record | Decision |\n|---|---|---|---|\n");
        for (k, s, a, c) in &active {
            out.push_str(&format!(
                "| {} | {} | {} | {} |\n",
                cell(k),
                scope_cell(s),
                a,
                cell(c)
            ));
        }
    }

    out.push_str("\n## Undecided\n\n");
    if undecided.is_empty() {
        out.push_str("None.\n");
    } else {
        for k in &undecided {
            out.push_str(&format!("- {}\n", cell(k)));
        }
    }

    out.push_str("\n## Retired\n\n");
    if retired.is_empty() {
        out.push_str("None.\n");
    } else {
        out.push_str("| Key | Scope | Record |\n|---|---|---|\n");
        for (k, s, a) in &retired {
            out.push_str(&format!("| {} | {} | {} |\n", cell(k), scope_cell(s), a));
        }
    }
    out
}

/// Slots that would be rendered, for callers that want the data not the text.
pub fn head_slots(g: &Graph) -> Vec<Slot<'_>> {
    g.corpus()
        .slots()
        .into_iter()
        .filter(|s| g.heads(*s).len() == 1)
        .collect()
}

/// Normalise away the differences a markdown formatter makes, and nothing else.
///
/// `HEADS.md` lives in repositories that run prettier, dprint or mdformat over
/// their markdown, and those pad table cells and rewrite the delimiter row.
/// Byte comparison called that stale forever. Comparing *canonicalised* forms
/// instead accepts the formatting and still rejects every edit that changes
/// what the file says.
///
/// This is deliberately a whitelist rather than a parser. A reader that turned
/// the file into rows and compared those would ignore whatever it did not
/// model, so a paragraph added under the banner — or a banner rewritten to say
/// the file is maintained by hand — would compare equal and pass forever.
/// Anything not named below survives into the comparison and shows up as a
/// difference, which is the property byte comparison had and the one worth
/// keeping.
///
/// The one escape it does decode is a CommonMark backslash escape of ASCII
/// punctuation inside a table cell (`\*` means `*`), because a formatter adds
/// and drops those. The decoded text is re-encoded with `cell()`'s own
/// escaping (`\` and `|`), so an escaped pipe stays distinct from a column
/// split. Inside a backtick code span a backslash is literal and nothing is
/// decoded. Applied to both sides, so a mistake in `cell()` is made
/// identically to the file and to the render.
pub fn canonicalise(text: &str) -> String {
    let text = text.strip_prefix('\u{feff}').unwrap_or(text);
    let mut out = String::with_capacity(text.len());
    for line in text.replace("\r\n", "\n").lines() {
        let line = line.trim_end();
        out.push_str(&canonical_row(line));
        out.push('\n');
    }
    // `render` ends in exactly one newline; a formatter may leave none or
    // several, and neither says anything.
    while out.ends_with("\n\n") {
        out.pop();
    }
    out
}

/// A table row with its padding removed, or the line unchanged.
///
/// The delimiter row collapses to `|---|` per column, so `| :--- |` and
/// `|---|` agree. Column *alignment* markers are dropped with the padding:
/// the projection never emits one, so a file carrying one differs from the
/// render in a way no formatter introduced.
fn canonical_row(line: &str) -> String {
    let t = line.trim();
    if !t.starts_with('|') || !t.ends_with('|') || t.len() < 2 {
        return line.to_string();
    }
    let inner = &t[1..t.len() - 1];
    let fields: Vec<&str> = split_unescaped(inner);
    let mut out = String::from("|");
    for f in fields {
        let f = f.trim();
        if is_delimiter_field(f) {
            out.push_str("---|");
        } else {
            out.push_str(&decode_cell(&minimal_fences(f)));
            out.push('|');
        }
    }
    out
}

/// The ASCII punctuation CommonMark lets a backslash escape.
const ASCII_PUNCTUATION: &str = "!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~";

/// Decode CommonMark backslash escapes in one left-to-right pass, skipping
/// backtick code spans, and re-encode as `cell()` does.
fn decode_cell(f: &str) -> String {
    let chars: Vec<char> = f.chars().collect();
    let mut decoded = String::with_capacity(f.len());
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '`' {
            let run = chars[i..].iter().take_while(|&&x| x == '`').count();
            // A span closes at the next run of exactly the same length. With
            // none, the backticks are literal text and decoding goes on.
            let mut j = i + run;
            let mut close = None;
            while j < chars.len() {
                if chars[j] == '`' {
                    let r = chars[j..].iter().take_while(|&&x| x == '`').count();
                    if r == run {
                        close = Some(j + r);
                        break;
                    }
                    j += r;
                } else {
                    j += 1;
                }
            }
            match close {
                Some(end) => {
                    // Literal inside the span; already in `cell()` form.
                    decoded.extend(chars[i..end].iter());
                    i = end;
                }
                None => {
                    decoded.extend(chars[i..i + run].iter());
                    i += run;
                }
            }
        } else if c == '\\' && i + 1 < chars.len() && ASCII_PUNCTUATION.contains(chars[i + 1]) {
            match chars[i + 1] {
                '\\' => decoded.push_str("\\\\"),
                '|' => decoded.push_str("\\|"),
                x => decoded.push(x),
            }
            i += 2;
        } else {
            // Not an escape (a backslash before a non-punctuation character
            // is a literal one), and any other character is itself.
            decoded.push(c);
            i += 1;
        }
    }
    decoded
}

/// `---`, `:---`, `---:` or `:---:` — the shapes a formatter writes for the
/// row under a table header.
fn is_delimiter_field(f: &str) -> bool {
    let core = f.trim_start_matches(':').trim_end_matches(':');
    !core.is_empty() && core.chars().all(|c| c == '-')
}

/// Split on `|` that is not escaped. A `|` is escaped when an odd number of
/// backslashes precedes it, which is why `cell()` has to escape the backslash.
fn split_unescaped(s: &str) -> Vec<&str> {
    let b = s.as_bytes();
    let mut out = Vec::new();
    let mut start = 0;
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'|' {
            let mut back = 0;
            let mut j = i;
            while j > start && b[j - 1] == b'\\' {
                back += 1;
                j -= 1;
            }
            if back % 2 == 0 {
                out.push(&s[start..i]);
                start = i + 1;
            }
        }
        i += 1;
    }
    out.push(&s[start..]);
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    const CANON: &str = "\
# Architecture decision heads

Generated by `greentopo heads --write`. Do not edit.

## Active

| Key | Scope | Record | Decision |
|---|---|---|---|
| a.b | — | ADR-0001 | One |
| c.d | cloud | ADR-0002 | Two |

## Undecided

None.

## Retired

None.
";

    fn same(a: &str, b: &str) -> bool {
        canonicalise(a) == canonicalise(b)
    }

    #[test]
    fn padding_and_delimiter_style_are_formatting() {
        // What prettier actually does: pad every cell to the column width and
        // rewrite `|---|` as `| --- |`.
        let pretty = CANON.replace(
            "| Key | Scope | Record | Decision |\n|---|---|---|---|\n\
                 | a.b | — | ADR-0001 | One |\n| c.d | cloud | ADR-0002 | Two |",
            "| Key | Scope | Record   | Decision |\n\
                 | --- | ----- | -------- | -------- |\n\
                 | a.b | —     | ADR-0001 | One      |\n\
                 | c.d | cloud | ADR-0002 | Two      |",
        );
        assert_ne!(pretty, CANON, "the fixture must actually differ");
        assert!(same(&pretty, CANON));
    }

    #[test]
    fn alignment_markers_are_formatting() {
        let aligned = CANON.replace("|---|---|---|---|", "| :--- | ---: | :---: | --- |");
        assert!(same(&aligned, CANON));
    }

    #[test]
    fn line_endings_bom_and_trailing_space_are_formatting() {
        // CRLF must be tolerated rather than repaired: a Windows checkout with
        // autocrlf would otherwise be stale, get rewritten as LF, be converted
        // back on checkout, and never converge.
        assert!(same(&CANON.replace('\n', "\r\n"), CANON));
        assert!(same(&format!("\u{feff}{}", CANON), CANON));
        assert!(same(&CANON.replace(" |\n", " |   \n"), CANON));
        assert!(same(&format!("{}\n\n\n", CANON), CANON));
        assert!(same(CANON.trim_end(), CANON));
    }

    #[test]
    fn a_changed_row_is_not_formatting() {
        assert!(!same(&CANON.replace("ADR-0001", "ADR-0009"), CANON));
        assert!(!same(
            &CANON.replace("| One |", "| Something else |"),
            CANON
        ));
    }

    #[test]
    fn an_added_or_removed_row_is_not_formatting() {
        assert!(!same(
            &CANON.replace("| c.d | cloud | ADR-0002 | Two |\n", ""),
            CANON
        ));
        assert!(!same(
            &CANON.replace(
                "| c.d | cloud | ADR-0002 | Two |\n",
                "| c.d | cloud | ADR-0002 | Two |\n| e.f | — | ADR-0003 | Three |\n",
            ),
            CANON
        ));
    }

    #[test]
    fn reordering_is_not_formatting() {
        // The projection is sorted (section 12). If a reordering were fresh,
        // nothing would enforce the sort any more.
        let swapped = CANON.replace(
            "| a.b | — | ADR-0001 | One |\n| c.d | cloud | ADR-0002 | Two |",
            "| c.d | cloud | ADR-0002 | Two |\n| a.b | — | ADR-0001 | One |",
        );
        assert!(!same(&swapped, CANON));
    }

    /// The trap a semantic reader would fall into: prose it does not model is
    /// prose it ignores, so the edit passes forever and an idempotent write
    /// then preserves it.
    #[test]
    fn added_prose_and_an_edited_banner_are_not_formatting() {
        assert!(!same(
            &CANON.replace("## Undecided", "Note: under review.\n\n## Undecided"),
            CANON
        ));
        assert!(!same(
            &CANON.replace("Do not edit.", "Maintained by hand."),
            CANON
        ));
        assert!(!same(
            &CANON.replace("## Retired", "## Retired decisions"),
            CANON
        ));
    }

    #[test]
    fn an_em_dash_a_formatter_replaced_is_not_formatting() {
        // No formatter should do this, and if one does the answer is to notice
        // rather than to guess that `--` meant the default scope.
        assert!(!same(&CANON.replace(" — ", " -- "), CANON));
    }

    #[test]
    fn a_pipe_in_a_cell_survives_and_a_backslash_before_it_does_too() {
        // `cell()` escapes the backslash first, so these are decodable. The
        // canonicaliser never has to decode them — it is applied to both sides
        // — but a wrong split must not merge two columns into one either.
        assert_eq!(cell("A|B"), "A\\|B");
        assert_eq!(cell("A\\|B"), "A\\\\\\|B");
        assert_eq!(split_unescaped(" a \\| b | c "), vec![" a \\| b ", " c "]);
        assert_eq!(cell("  padded  "), "padded");
    }
    #[test]
    fn a_formatters_escaped_punctuation_is_formatting() {
        let render = "| a.b | — | ADR-0001 | snake_case and * glob |\n";
        let pretty = "| a.b | — | ADR-0001 | snake\\_case and \\* glob |\n";
        assert!(same(pretty, render));
        assert!(!same(
            "| a.b | — | ADR-0001 | snakecase and * glob |\n",
            render
        ));
    }

    #[test]
    fn an_escaped_pipe_is_not_a_column_split() {
        assert!(!same("| a \\| b |\n", "| a | b |\n"));
        assert!(same("| a \\| b |\n", "| a \\| b |\n"));
    }

    #[test]
    fn an_escaped_backslash_equals_itself() {
        let r = format!("| {} |\n", cell("a\\b"));
        assert!(same(&r, &r));
        assert!(!same(&r, "| ab |\n"));
        assert_eq!(canonicalise(&r), canonicalise(&r.replace("  ", " ")));
    }

    #[test]
    fn a_backslash_before_a_non_punctuation_character_is_untouched() {
        assert_eq!(canonicalise("| a\\b |\n"), "|a\\b|\n");
        assert!(!same("| a\\b |\n", "| ab |\n"));
    }

    #[test]
    fn prettier_escaping_after_an_escaped_backslash_equals_the_render() {
        let render = format!("| {} |\n", cell("a\\*"));
        assert_eq!(render, "| a\\\\* |\n");
        assert!(same(&render, "| a\\\\\\* |\n"));
        assert!(!same(&render, "| a\\\\ |\n"));
    }

    #[test]
    fn an_escaped_angle_bracket_and_backtick_decode_like_an_asterisk() {
        assert!(same("| a \\< b |\n", "| a < b |\n"));
        assert!(same("| a \\` b |\n", "| a ` b |\n"));
        assert!(!same("| a \\< b |\n", "| a > b |\n"));
    }

    #[test]
    fn inside_a_code_span_an_escape_is_literal() {
        assert!(!same("| `a\\*b` |\n", "| `a*b` |\n"));
        assert!(same("| `a\\*b` \\* |\n", "| `a\\*b` * |\n"));
    }

    #[test]
    fn an_unbalanced_backtick_swallows_nothing() {
        assert!(same("| a ` b \\* c |\n", "| a ` b * c |\n"));
        assert!(same("| `` a ` b \\* c |\n", "| `` a ` b * c |\n"));
    }

    #[test]
    fn the_escapable_set_is_the_ascii_punctuation() {
        assert_eq!(ASCII_PUNCTUATION.chars().count(), 32);
        assert!(ASCII_PUNCTUATION.chars().all(|c| c.is_ascii_punctuation()));
    }

    /// The expected text is prettier's own output (3.5.3 and 3.8.3 agree) for
    /// the compact table, so a change here is checked against the formatter
    /// rather than against a recollection of it.
    #[test]
    fn align_matches_prettier_widths() {
        let compact = "| A | B |\n|---|---|\n| — | x |\n| … · × € ± î | x |\n\
                       | 🧑 | x |\n| 👉📍 | x |\n| 漢字 | x |\n| ❤️ | x |\n\
                       | 🧑\u{200d}💻 | x |\n| é | x |\n| 👍🏽 | x |\n| ab | y |\n\
                       | ``a `b` c`` | `safe to x` |\n| `` `x` `` | `a``b` |\n\
                       | a \\| b | `c \\| d` |\n";
        let prettier = "\
| A           | B           |
| ----------- | ----------- |
| —           | x           |
| … · × € ± î | x           |
| 🧑          | x           |
| 👉📍        | x           |
| 漢字        | x           |
| ❤️          | x           |
| 🧑\u{200d}💻          | x           |
| é           | x           |
| 👍🏽          | x           |
| ab          | y           |
| ``a `b` c`` | `safe to x` |
| `` `x` ``   | `a``b`      |
| a \\| b      | `c \\| d`    |
";
        assert_eq!(align(compact), prettier);
    }

    #[test]
    fn a_column_is_three_wide_at_least_and_prose_passes_through() {
        let text = "# H\n\nSome text.\n\n| K |\n|---|\n| a |\n\n- b\n";
        assert_eq!(
            align(text),
            "# H\n\nSome text.\n\n| K   |\n| --- |\n| a   |\n\n- b\n"
        );
    }

    /// A fence is formatting: the file written before this, with the fence the
    /// record used, and the file prettier wrote are both current.
    #[test]
    fn a_code_span_fence_is_formatting() {
        let render = "| K |\n|---|\n| ends with ``safe; next: `<p>` `` here |\n";
        // prettier 3.5.3 leaves this span as it is.
        let prettier = "| K                                     |\n\
                        | ------------------------------------- |\n\
                        | ends with ``safe; next: `<p>` `` here |\n";
        let narrowed = "| K |\n|---|\n| run ``x`` |\n";
        assert!(same(&align(render), render));
        assert!(same(prettier, render));
        assert!(same(narrowed, "| K |\n|---|\n| run `x` |\n"));
        assert!(!same(narrowed, "| K |\n|---|\n| run x |\n"));
    }

    /// Narrowing a fence must never let an earlier unclosed run close against
    /// it, or `--write` then `--check` would disagree with itself.
    #[test]
    fn fences_are_idempotent_and_a_written_file_is_current() {
        for c in [
            "``x ```a`b```",
            "``safe to x`` and ```y```",
            "a \\` ``b``",
            "`` `x` `` ```z```",
        ] {
            let once = minimal_fences(c);
            assert_eq!(minimal_fences(&once), once, "{c}");
            let row = format!("| K |\n|---|\n| {c} |\n");
            assert!(same(&align(&row), &row), "{c}");
        }
    }

    /// A hand-edited short row keeps its cell count when aligned.
    #[test]
    fn a_short_row_is_not_padded_out() {
        let t = "| A | B |\n|---|---|\n| x |\n";
        assert_eq!(align(t), "| A   | B   |\n| --- | --- |\n| x   |\n");
    }

    /// Alignment is formatting: the aligned render is the render.
    #[test]
    fn an_aligned_render_canonicalises_to_the_render() {
        assert!(same(&align(CANON), CANON));
        assert_ne!(align(CANON), CANON);
    }

    /// prettier's fence for each span, as it printed them.
    #[test]
    fn a_code_span_takes_prettiers_fence() {
        assert_eq!(
            minimal_fences("ends with ``safe to /clear``"),
            "ends with `safe to /clear`"
        );
        assert_eq!(minimal_fences("`` a `b` c ``"), "``a `b` c``");
        assert_eq!(minimal_fences("`` `x` ``"), "`` `x` ``");
        assert_eq!(minimal_fences("```a``b```"), "`a``b`");
        assert_eq!(minimal_fences("`plain` and `` `` x"), "`plain` and ` ` x");
        assert_eq!(minimal_fences("`  a  `"), "`  a  `");
        assert_eq!(minimal_fences("` a`"), "` a`");
        assert_eq!(minimal_fences("a ``b"), "a ``b");
        assert_eq!(minimal_fences("``x ```a`b```"), "``x ```a`b```");
        assert_eq!(minimal_fences("`` `x` `` and ``y``"), "`` `x` `` and `y`");
        assert_eq!(minimal_fences("x \\` ``y`` z"), "x \\` `y` z");
        assert_eq!(minimal_fences("``x`` and ` stray"), "`x` and ` stray");
    }
}
